class ButterworthAnalogPoleGenerator:
    def __init__(self):
        self.reset()

    def reset(self):
        pass

    def process(self, in_n):
        n = in_n & 0xFFFFFFFF
        n = n if n <= 16 else 16
        return [{"out_kind": 0, "out_real": r, "out_imag": i} for r, i in POLES[n]] + [
            {"out_kind": 1, "out_real": 0x3F800000, "out_imag": 0x00000000}
        ]
